module.exports = function(RED) {
    "use strict";

    var mqtt = require("mqtt");
    var Readable = require("stream").Readable;
    var caps = require("./lib/meo-caps");
    var topics = require("./lib/meo-topics");
    var deviceEvent = require("./lib/meo-event");
    var deviceCommand = require("./lib/meo-command");

    var DEVICE_LIST_TIMEOUT = 5000;
    // Per docs/mqtt_messaging.md: commands are QoS 1, replies and events QoS 0.
    var COMMAND_QOS = 1;
    var SUBSCRIBE_QOS = 0;
    // Matches MeoControlHandler.REPLY_TIMEOUT_MS, so moving commands off the
    // HTTP API does not change how long a flow waits.
    var REPLY_TIMEOUT = 10000;
    // The gateway image ships the broker alongside Node-RED and the service, so
    // the broker address is not configurable — it is always the gateway's, on
    // the MQTT default port (matching the service's MEO_MQTT_BROKER default).
    var BROKER_PORT = 1883;

    var STATUS = {
        connecting: { fill: "yellow", shape: "ring", text: "node-red:common.status.connecting" },
        connected: { fill: "green", shape: "dot", text: "node-red:common.status.connected" },
        disconnected: { fill: "red", shape: "ring", text: "node-red:common.status.disconnected" }
    };

    function MeoGatewayNode(n) {
        RED.nodes.createNode(this, n);
        var node = this;
        node.name = n.name;
        node.host = n.host || "localhost";
        node.port = Number(n.port) || 7070;

        node.apiUrl = function() {
            return "http://" + node.host + ":" + node.port;
        };

        node.brokerUrl = function() {
            return "mqtt://" + node.host + ":" + BROKER_PORT;
        };

        // ── Device messaging ──────────────────────────────────────────────
        // One connection per gateway shared by every MEO node using it: connect
        // on the first, disconnect on the last. The HTTP API is still used for
        // the device registry.

        var listeners = {};
        var client = null;
        // Keyed deviceId#cap, not requestId: ours is constant (lib/meo-command.js).
        var pending = {};

        node.registerListener = function(listener) {
            var first = Object.keys(listeners).length === 0;
            listeners[listener.id] = listener;
            if (first) {
                connect();
            }
            // Deferred: a status set mid-construction does not reach the editor.
            setTimeout(function() {
                if (listeners[listener.id]) { setStatus(listener); }
            }, 0);
        };

        node.deregisterListener = function(listener, done) {
            delete listeners[listener.id];
            if (Object.keys(listeners).length === 0) {
                disconnect(done);
                return;
            }
            done();
        };

        function connect() {
            client = mqtt.connect(node.brokerUrl(), {
                clientId: "meo-nodered-" + RED.util.generateId(),
                reconnectPeriod: RED.settings.mqttReconnectTime || 5000,
                clean: true
            });
            client.on("connect", function() {
                // Re-subscribes on every reconnect: clean session, so the broker
                // keeps nothing for us across a drop.
                var wildcards = [topics.EVENT_WILDCARD, topics.REPLY_WILDCARD];
                client.subscribe(wildcards, { qos: SUBSCRIBE_QOS }, function(err) {
                    if (err) {
                        node.error(RED._("meo.errors.subscribeFailed",
                            { topic: wildcards.join(", "), message: err.message }));
                        return;
                    }
                    node.log(RED._("meo.events.subscribed",
                        { topic: wildcards.join(", "), broker: node.brokerUrl() }));
                    broadcastStatus();
                });
            });
            client.on("reconnect", broadcastStatus);
            client.on("close", broadcastStatus);
            client.on("error", function(err) {
                node.error(err.message || RED._("meo.errors.brokerError"));
            });
            client.on("message", onMessage);
        }

        function disconnect(done) {
            if (!client) {
                done();
                return;
            }
            var ending = client;
            client = null;
            // Forced: nothing of ours is in flight, and an unreachable broker
            // must not stall a deploy.
            ending.end(true, {}, done);
        }

        // Publishes a command and resolves with the value the device reports.
        node.sendCommand = function(deviceId, cap, value) {
            return new Promise(function(resolve, reject) {
                if (!client || !client.connected) {
                    reject(new Error(RED._("meo.errors.notConnected")));
                    return;
                }

                var key = deviceId + "#" + cap;
                // A second command to the same capability supersedes the first;
                // its caller would otherwise hang until the timeout.
                if (pending[key]) {
                    pending[key].settle(new Error(RED._("meo.errors.superseded")));
                }

                var timer = setTimeout(function() {
                    settle(new Error(RED._("meo.errors.noReply")));
                }, REPLY_TIMEOUT);

                function settle(err, result) {
                    if (!pending[key]) { return; }
                    delete pending[key];
                    clearTimeout(timer);
                    if (err) { reject(err); } else { resolve(result); }
                }

                pending[key] = { deviceId: deviceId, cap: cap, settle: settle };

                client.publish(topics.command(deviceId), deviceCommand.build(cap, value),
                    { qos: COMMAND_QOS }, function(err) {
                        if (err) { settle(err); }
                    });
            });
        };

        function onMessage(topic, payload) {
            var deviceId = topics.deviceIdFromTopic(topic);
            if (deviceId === null) {
                return;
            }
            if (topic.endsWith("/reply")) {
                onReply(deviceId, topic, payload);
            } else {
                onEvent(deviceId, topic, payload);
            }
        }

        function onEvent(deviceId, topic, payload) {
            var frame = deviceEvent.parse(payload);
            if (frame === null) {
                node.debug("dropping malformed event frame on " + topic +
                    " (" + (payload ? payload.length : 0) + " bytes)");
                return;
            }
            Object.keys(listeners).forEach(function(id) {
                var listener = listeners[id];
                // Command nodes register for the connection but take no events.
                if (typeof listener.onDeviceEvent === "function") {
                    listener.onDeviceEvent(deviceId, frame.cap, frame.value);
                }
            });
        }

        function onReply(deviceId, topic, payload) {
            var frame = deviceCommand.parseReply(payload);
            if (frame === null) {
                node.debug("dropping malformed reply frame on " + topic +
                    " (" + (payload ? payload.length : 0) + " bytes)");
                return;
            }
            // On failure the device zeroes cap, so attribute it to the oldest
            // outstanding command: firmware handles them one at a time and QoS 1
            // keeps the order.
            var entry = pending[deviceId + "#" + frame.cap] ||
                (frame.ok ? null : oldestPendingFor(deviceId));
            if (!entry) {
                // Timed out already, or a reply to the gateway service's own
                // command — both are normal, neither is ours.
                node.debug("no pending command for reply on " + topic);
                return;
            }
            if (!frame.ok) {
                entry.settle(new Error(deviceErrorMessage(frame.error)));
                return;
            }
            entry.settle(null, caps.kindOf(entry.cap) === "read" ? frame.valueFloat : frame.valueInt);
        }

        // Insertion order: object string keys preserve it, so the first match
        // is the longest-outstanding command.
        function oldestPendingFor(deviceId) {
            var key = Object.keys(pending).find(function(k) {
                return pending[k].deviceId === deviceId;
            });
            return key ? pending[key] : null;
        }

        // Mirrors MeoControlHandler.deviceErrorMessage.
        function deviceErrorMessage(error) {
            if (error === 1) { return RED._("meo.errors.badRequest"); }
            if (error === 2) { return RED._("meo.errors.capNotSupported"); }
            if (error === 3) { return RED._("meo.errors.handleFailed"); }
            return RED._("meo.errors.deviceError", { error: error });
        }

        function setStatus(listener) {
            listener.status(client && client.connected ? STATUS.connected : STATUS.connecting);
        }

        function broadcastStatus() {
            var status = client && client.connected ? STATUS.connected : STATUS.disconnected;
            Object.keys(listeners).forEach(function(id) {
                listeners[id].status(status);
            });
        }

        node.on("close", function(done) {
            listeners = {};
            disconnect(done);
        });
    }
    RED.nodes.registerType("meo-gateway", MeoGatewayNode);

    // ── Editor support ────────────────────────────────────────────────
    // The edit dialogs go through here rather than calling the gateway from
    // the browser: the runtime shares a host with the gateway, the browser
    // may not (open the editor from a laptop and "localhost" is the laptop).

    RED.httpAdmin.get("/meo/capabilities", RED.auth.needsPermission("meo-gateway.read"), function(req, res) {
        res.json(caps.list());
    });

    // Host/port come from the query, not from a deployed config node, so the
    // device list works while the gateway node is still being filled in.
    RED.httpAdmin.get("/meo/devices", RED.auth.needsPermission("meo-gateway.read"), function(req, res) {
        var host = req.query.host;
        var port = Number(req.query.port);
        if (!/^[A-Za-z0-9._-]+$/.test(host || "")) {
            res.status(400).json({ message: "invalid gateway host" });
            return;
        }
        if (!(port > 0 && port < 65536)) {
            res.status(400).json({ message: "invalid gateway port" });
            return;
        }
        fetch("http://" + host + ":" + port + "/api/v1/devices", {
            signal: AbortSignal.timeout(DEVICE_LIST_TIMEOUT)
        }).then(function(response) {
            if (!response.ok) {
                throw new Error("gateway returned " + response.status);
            }
            return response.json();
        }).then(function(devices) {
            // Resolve each device's declared ids here so the edit dialogs never
            // have to re-implement the kind-from-id-range rule.
            res.json((devices || []).map(function(device) {
                device.caps = caps.commandable(device.capabilities);
                device.eventCaps = caps.reportable(device.capabilities);
                return device;
            }));
        }).catch(function(err) {
            // Unreachable gateway is the common case here, not a server fault.
            res.status(502).json({ message: err.message || "gateway unreachable" });
        });
    });

    // ── Sidebar proxy ─────────────────────────────────────────────────
    // The MEO sidebar reaches the service through here for the same reason the
    // dialogs do. Unlike /meo/devices above there is no host to pass: the
    // sidebar manages *this* gateway, which is always the machine the runtime
    // runs on.
    var SERVICE_URL = (process.env.MEO_API_URL || "http://localhost:7070").replace(/\/+$/, "");
    // The service's scan blocks for DEFAULT_SCAN_TIMEOUT_MS (8s), so this ceiling
    // has to clear it with room to spare.
    var PROXY_TIMEOUT = 30000;

    function proxyPermission(req, res, next) {
        RED.auth.needsPermission(req.method === "GET" ? "meo-gateway.read" : "meo-gateway.write")(req, res, next);
    }

    // Registered before the catch-all: SSE has to stream, not buffer.
    // EventSource cannot send an auth header, so with adminAuth enabled this
    // route would 401 — the shipped gateway sets no adminAuth.
    // ponytail: query-param token if that ever changes.
    RED.httpAdmin.get("/meo/api/provision/events", function(req, res) {
        var upstream = new AbortController();
        req.on("close", function() { upstream.abort(); });
        fetch(SERVICE_URL + "/api/v1/provision/events", {
            headers: { accept: "text/event-stream" },
            signal: upstream.signal
        }).then(function(response) {
            if (!response.ok || !response.body) {
                throw new Error("service returned " + response.status);
            }
            // no-transform keeps compression middleware from holding events back.
            res.writeHead(200, {
                "content-type": "text/event-stream",
                "cache-control": "no-cache, no-transform",
                "connection": "keep-alive"
            });
            res.flushHeaders();
            Readable.fromWeb(response.body)
                .on("error", function() { res.end(); })
                .pipe(res);
        }).catch(function(err) {
            if (!res.headersSent) {
                res.status(502).json({ message: err.message || "service unreachable" });
            } else {
                res.end();
            }
        });
    });

    RED.httpAdmin.all("/meo/api/*", proxyPermission, function(req, res) {
        var query = req.originalUrl.indexOf("?");
        var url = SERVICE_URL + "/api/v1/" + req.params[0] +
                  (query === -1 ? "" : req.originalUrl.slice(query));
        // adminApp parses JSON bodies before we see them, so re-serialize rather
        // than piping the (already consumed) request stream.
        var body = req.body && Object.keys(req.body).length > 0 ? JSON.stringify(req.body) : undefined;
        fetch(url, {
            method: req.method,
            headers: body ? { "content-type": "application/json" } : undefined,
            body: body,
            signal: AbortSignal.timeout(PROXY_TIMEOUT)
        }).then(function(response) {
            return response.text().then(function(text) {
                res.status(response.status);
                var type = response.headers.get("content-type");
                if (type) { res.set("content-type", type); }
                res.send(text);
            });
        }).catch(function(err) {
            res.status(502).json({ message: err.message || "service unreachable" });
        });
    });
};
